class Routes:
    """Active routing plan: null or full per-pair weighted path bundles."""

    def __init__(self, raw, topo):
        if raw is None:
            self.bundles = None
            self.key = None
            return
        bundles = {}
        entries = []
        for sname, dbundle in raw.items():
            sid = topo.id_of[sname]
            for dname, items in dbundle.items():
                did = topo.id_of[dname]
                lst = []
                for item in items:
                    path = tuple(item["path"])
                    weight = item["weight"]
                    lst.append((path, weight))
                    entries.append((sname, dname, path, weight))
                bundles[(sid, did)] = tuple(lst)
        self.bundles = bundles
        self.key = tuple(sorted(entries))

    def internal_predictions(self, topo, demands):
        """Floor after all contributions; never clamped here."""
        acc = {}
        for (sid, did), items in self.bundles.items():
            demand = demands.get((sid, did), 0)
            if demand == 0:
                continue
            for (path, weight) in items:
                contrib = demand * weight
                for a, b in zip(path, path[1:]):
                    fi = topo.flow_index[(topo.id_of[a], topo.id_of[b])]
                    acc[fi] = acc.get(fi, 0) + contrib
        total = len(topo.flows)
        return [acc.get(i, 0) // 1000 for i in range(total)]


def _is_int(value):
    return type(value) is int


