        self.trials = settings["trials"]
        self.epsilon = settings["epsilon"]
        self.seed = settings["seed"]
        self.cutoff = (settings["cutoff"][0], settings["cutoff"][1])
        self.bias = settings["bias"]
        self.tau = settings["tau"]
        self.gamma = (settings["gamma"][0], settings["gamma"][1])
        self.cache_slots = settings["cache_slots"]

        self.counters = {key: MISSING for key in self.topo.all_keys}
        self.demands = {pair: 0 for pair in self.topo.demand_pairs}
        self.routes = None
        self.cache = RepairCache(self.cache_slots)
        self.snapshots = {}
        self.wmemo = {}
        self._predictions = None

